import type { RouteDefinition } from '../types';
import { cleanPath, normalizeRoutePattern, splitSegments } from '../matcher/normalizer';

const HTTP_METHODS = ['get', 'post', 'put', 'delete', 'patch', 'options', 'head'] as const;

/**
 * Parses an OpenAPI 3.0 or Swagger 2.0 document generated by `@nestjs/swagger` into standard RouteDefinitions.
 *
 * @param swaggerDoc - The parsed OpenAPI / Swagger document object from `SwaggerModule.createDocument`.
 * @returns Array of harvested route definitions with paths, methods, summaries, and operation IDs.
 */
export function parseSwaggerDoc(swaggerDoc: any): RouteDefinition[] {
  if (!swaggerDoc || typeof swaggerDoc !== 'object' || !swaggerDoc.paths) {
    return [];
  }

  const routes: RouteDefinition[] = [];
  const pathsObj = swaggerDoc.paths;

  for (const rawPath of Object.keys(pathsObj)) {
    const pathItem = pathsObj[rawPath];
    if (!pathItem || typeof pathItem !== 'object') continue;

    // Convert OpenAPI curly param format (/users/{id}) to NestJS format (/users/:id)
    const normalizedNestPath = rawPath.replace(/\{([^}]+)\}/g, ':$1');
    const path = cleanPath(normalizedNestPath);
    const segments = splitSegments(path);
    const normalizedPattern = normalizeRoutePattern(path);

    for (const methodKey of HTTP_METHODS) {
      const operation = pathItem[methodKey];
      if (!operation || typeof operation !== 'object') continue;

      routes.push({
        method: methodKey.toUpperCase(),
        path,
        normalizedPattern,
        segments,
        summary: operation.summary ?? operation.description,
        operationId: operation.operationId,
      });
    }
  }

  return routes;
}
